/**
 * 演示模块：把标题转成 URL slug。
 */

/** 生成 slug，支持自定义分隔符与最大长度截断。 */
export function slugify(input, options = {}) {
  const separator = options.separator ?? '-'
  const maxLength = options.maxLength
  let out = String(input).trim().toLowerCase().replace(/\s+/g, separator)
  if (typeof maxLength === 'number' && maxLength > 0 && out.length > maxLength) {
    out = out.slice(0, maxLength)
    while (out.endsWith(separator)) out = out.slice(0, -1)
  }
  return out
}
